sealed class StubHandler : HttpMessageHandler {
    protected override Task<HttpResponseMessage> SendAsync(
        HttpRequestMessage request, CancellationToken ct) =>
        Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) {
            Content = JsonContent.Create(new { price = 9.99m })
        });
}
var client = new PricesClient(new HttpClient(new StubHandler()) { BaseAddress = uri });

sealed class FakePriceService(IReadOnlyDictionary<string, decimal> canned) : IPriceService {
    public Task<decimal> GetPriceAsync(string sku, CancellationToken ct) =>
        canned.TryGetValue(sku, out var price)
            ? Task.FromResult(price)
            : Task.FromException<decimal>(new UnknownSkuException(sku));
}
